#include "../../models/film_three_finger_resume/FaceEdgeTransfer.h"
#include <fstream>
#include <iostream>
#include <iomanip>
using namespace regrip_three_resume;
int main(int argc,char**argv){try{
 if(argc!=3&&argc!=4)throw std::runtime_error("checkpoint,prefix required");std::ifstream in(argv[1]);std::string magic,token;double time,h;unsigned step;in>>magic>>time>>h>>step>>token;SharedFilmSystem s(Layout(),{0,0,-.001},true,true);s.exactUnresolved=true;unsigned n=s.initial.size(),nf=s.shared.nf;Eigen::VectorXd q(n),v(n);for(double&x:q)in>>x;for(double&x:v)in>>x;double unused;for(unsigned i=0;i<4;++i)in>>unused;s.shared.M.setZero();for(unsigned f=0;f<3;++f){auto&m=s.shared.films[f].film;for(unsigned i=0;i<m.mass.size();++i){double mass;in>>mass;m.mass[i]=mass;for(unsigned d=0;d<3;++d){unsigned a=3*i+d;if(m.index[a]>=0)s.shared.M(f*nf+m.index[a],f*nf+m.index[a])+=mass*m.weight[a]*m.weight[a];}}}for(unsigned i=0;i<6;++i)for(unsigned j=0;j<6;++j)in>>s.shared.M(3*nf+i,3*nf+j);if(!in)throw std::runtime_error("checkpoint incomplete");auto result=faceEdgeTransfer(s,q,v,time,h);std::string prefix=argv[2];std::ofstream metrics(prefix+".metrics.csv");metrics<<std::setprecision(17)<<"event_time_s,event_fraction_s,bracket_width_s,minimum_face_parameter,minimum_independent_gap_mm,J_continuity_max,edge_initial_normal_velocity_mm_s,minimum_stage_gap_mm,pre_momentum_Ns,post_momentum_Ns,post_normal_velocity_mm_s,evaluations\n"<<time+result.eventH<<','<<result.eventH<<','<<result.bracketWidth<<','<<result.minimumFaceParameter<<','<<result.minimumIndependentGap<<','<<result.Jcontinuity<<','<<result.edgeNormalVelocity<<','<<result.minimumGap<<','<<result.pre.momentumResidual<<','<<result.post.momentumResidual<<','<<result.post.velocityResidual<<','<<result.evaluations<<'\n';std::ofstream states(prefix+".states.txt");states<<std::setprecision(17)<<"EVENT "<<time+result.eventH<<'\n'<<result.pre.q.transpose()<<'\n'<<result.pre.v.transpose()<<"\nEND "<<time+h<<'\n'<<result.post.q.transpose()<<'\n'<<result.post.v.transpose()<<'\n';std::ofstream owners(prefix+".edges.csv");owners<<"finger,source_triangle,node0,node1\n";for(const auto&e:result.edges)owners<<e.finger<<','<<e.sourceTriangle<<','<<e.nodes[0]<<','<<e.nodes[1]<<'\n';if(argc==4){unsigned steps=std::stoul(argv[3]);if(steps>4)throw std::runtime_error("profiled extra edge steps0..4 only");Eigen::VectorXd nextq=result.post.q,nextv=result.post.v;double clock=time+h;std::ofstream continuation(prefix+".continuation.csv");continuation<<std::setprecision(17)<<"time,minimum_gap,momentum,normal_velocity,q,v\n";for(unsigned i=0;i<steps;++i){auto row=regrip_collocation::persistentRows(s.shared.M,2,nextq,nextv,clock,h,[&](const auto&x,double t){return s.force(x,regrip_film_rail::ControlProfile::evaluate(t,.0001,.01,.02,.03,true).tension);},[&](const auto&x){return edgeGeometry(s,x,result.edges);});double gap=s.clearance(row.q);for(const auto&stage:row.stages)gap=std::min(gap,s.clearance(stage.q));if(gap< -1e-10)throw std::runtime_error("continued owned-edge whole-stage clearance fails");nextq=row.q;nextv=row.v;clock+=h;continuation<<clock<<','<<gap<<','<<row.momentumResidual<<','<<row.velocityResidual;for(const auto*z:{&nextq,&nextv})continuation<<",\""<<z->transpose()<<'"';continuation<<'\n';continuation.flush();}}std::cout<<"PASS independent face-edge event and velocity-continuous owned-edge remainder;NOT SOFA/global CCD/fullcycle/grasp\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
